void init_GPIO(void)
{
    // Habilitamos el reloj del periférico GPIOB  para los leds salidas, GPIOA para el led de blinki y
    // GPIOC para el boton de entrada.
    
    RCC->AHB1ENR &= ~(RCC_AHB1ENR_GPIOBEN_Msk); // Bit 1 = 0: reloj deshabilitado.
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOBEN_Msk; // Bit 1 = 1: reloj habilitado.

    RCC->AHB1ENR &= ~(RCC_AHB1ENR_GPIOAEN_Msk); // Bit 0 = 0: reloj deshabilitado.
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN_Msk; // Bit 0 = 1: reloj habilitado.

    RCC->AHB1ENR &= ~(RCC_AHB1ENR_GPIOCEN_Msk); // Bit 2 = 0: reloj deshabilitado.
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN_Msk; // Bit 2 = 1: reloj habilitado.

    // habilitamos GPIOB8 , GPIOB9 y GPIOB6 como salida y son del mismo puerto podemos hacer lo siguiente.
    // Configuramos el pin PB8 como salida
    GPIOB->MODER &= ~(GPIO_MODER_MODE8 | GPIO_MODER_MODE9 | GPIO_MODER_MODE6); // Limpiamos los bits de modo para PB8, PB9 y PB6.
    GPIOB->MODER |= (GPIO_MODER_MODE8_0 | GPIO_MODER_MODE9_0 | GPIO_MODER_MODE6_0); // Configuramos PB8, PB9 y PB6 como salida (01).
    GPIOB->OTYPER &= ~(GPIO_OTYPER_OT8 | GPIO_OTYPER_OT9 | GPIO_OTYPER_OT6); // Configuramos PB8, PB9 y PB6 como salida push-pull (0).
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED8 | GPIO_OSPEEDR_OSPEED9 | GPIO_OSPEEDR_OSPEED6); // Configuramos PB8, PB9 y PB6 como baja velocidad (00).
    GPIOB->PUPDR &= ~(GPIO_PUPDR_PUPD8 | GPIO_PUPDR_PUPD9 | GPIO_PUPDR_PUPD6); // Configuramos PB8, PB9 y PB6 sin pull-up/pull-down (00).
    GPIOB->ODR &= ~(GPIO_ODR_OD8 | GPIO_ODR_OD9 | GPIO_ODR_OD6); // Inicializamos PB8, PB9 y PB6 en bajo (apagado).

    // Configuramos el pin PA5 como salida -- para el led de blinki
    GPIOA->MODER &= ~(GPIO_MODER_MODE5); // Limpiamos los bits de modo para PA5.
    GPIOA->MODER |= (GPIO_MODER_MODE5_0); // Configuramos PA5 como salida (01).
    GPIOA->OTYPER &= ~(GPIO_OTYPER_OT5); // Configuramos PA5 como salida push-pull (0).
    GPIOA->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED5); // Configuramos PA5 como baja velocidad (00).
    GPIOA->PUPDR &= ~(GPIO_PUPDR_PUPD5); // Configuramos PA5 sin pull-up/pull-down (00).
    GPIOA->ODR &= ~(GPIO_ODR_OD5); // Inicializamos PA5 en bajo (apagado).

    // Configuramos el pin PC13 como entrada -- para el boton de usuario
    GPIOC->MODER &= ~(GPIO_MODER_MODE13); // Limpiamos los bits de modo para PC13.
    GPIOC->MODER |= (GPIO_MODER_MODER13_Msk); // Configuramos PC13 como entrada (00).
    GPIOC->OTYPER &= ~(GPIO_OTYPER_OT13); // Configuramos PC13 como entrada push-pull (0).
    GPIOC->OSPEEDR &= ~(GPIO_OSPEEDR_OSPEED13); // Configuramos PC13 como baja velocidad (00).
    GPIOC->PUPDR &= ~(GPIO_PUPDR_PUPD13); // Configuramos PC13 sin pull-up/pull-down (00).
}

void Init_EXTI(void)
{
    //habilitamos el reloj del SYSCFG para poder configurar la línea de interrupción EXTI.
    RCC->APB2ENR &= ~RCC_APB2ENR_SYSCFGEN; // Bit 14 = 0: reloj deshabilitado.
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN; // Bit 14 = 1: reloj habilitado.

    SYSCFG->EXTICR[3] &= ~(SYSCFG_EXTICR4_EXTI13); // Limpiamos los bits de configuración para EXTI13.
    SYSCFG->EXTICR[3] |= (SYSCFG_EXTICR4_EXTI13_PC); // Configuramos EXTI13 para que esté conectado al pin PC13.

    EXTI->RTSR &= ~(EXTI_RTSR_TR13); // Limpiamos el bit de activación por flanco de subida para EXTI13 "sin disparo de subida".
    EXTI->FTSR |= (EXTI_FTSR_TR13); // Configuramos el bit de activación por flanco de bajada para EXTI13 "disparo de bajada".


    EXTI->PR = EXTI_PR_PR13; //Limpiamos la bandera pendiente
    EXTI->IMR &= ~(EXTI_IMR_MR13); // Limpiamos el bit de máscara para EXTI13 "sin interrupción".
    EXTI->IMR |= (EXTI_IMR_MR13); // Configuramos el bit de máscara para EXTI13 "con interrupción".

    // Configuramos el NVIC para la interrupción EXTI15_10 (que incluye EXTI13).
    NVIC_EnableIRQ(EXTI15_10_IRQn); // Habilitamos la interrupción en el NVIC.
}

void init_timer(void){
    RCC->APB1ENR |= RCC_APB1ENR_TIM2EN; //habilitamos el reloj para TIM2
    TIM2->PSC = 16000-1; //prescaler para contar en milisegundos (16Mhz / 16000 =1KHz)
    TIM2->ARR = 500-1;//Autoreload para 1/2 de segundo, es decir cuenta 500ms y luego levanta la bandera, ver el grafico de las notas
    TIM2->CNT = 0;

}

